<script setup>
import {onMounted,reactive,ref} from 'vue'
import {ensureInstructor} from '../lib/instructor'
import {authRequest,notify,state} from '../lib/state'
import OwnerTabs from '../components/OwnerTabs.vue'
const busy=ref(false),form=reactive({displayName:'',bio:'',link:'',accent:'terracota',coverImage:''})
onMounted(async()=>{try{await ensureInstructor();Object.assign(form,state.user?.studio||{})}catch(e){notify(e.message)}})
async function save(){try{busy.value=true;const res=await authRequest('/instructor/studio',{method:'PATCH',body:form});state.user.studio=res.item;notify('Perfil público actualizado.')}catch(e){notify(e.message)}finally{busy.value=false}}
</script>
<template><div class="page owner-page"><div class="page-heading"><div><div class="eyebrow earth">IDENTIDAD DEL TALLERISTA</div><h1>Personalizar mi perfil</h1><p class="muted">Muestra tu identidad, describe tu propuesta y comparte un enlace seguro.</p></div></div><OwnerTabs/><section class="form-card"><form class="form-grid" @submit.prevent="save"><label>Nombre del estudio<input v-model.trim="form.displayName" maxlength="90" placeholder="Ej. Estudio Meza"/></label><label>Tono del perfil<select v-model="form.accent"><option value="terracota">Naranja terracota</option><option value="oliva">Oliva</option><option value="azul">Azul suave</option></select></label><label class="span-all">Descripción del tallerista<textarea v-model.trim="form.bio" maxlength="900" rows="4" placeholder="Tu experiencia y estilo..."/></label><label class="span-all">Enlace público (HTTPS)<input v-model.trim="form.link" type="url" pattern="https://.*" maxlength="220" placeholder="https://sitio-ejemplo.pe"/></label><div class="span-all" :style="{borderLeft:`6px solid ${({terracota:'#c65c38',oliva:'#76905e',azul:'#648eaf'})[form.accent]}`,padding:'8px 14px'}">Vista previa: {{form.displayName||state.user?.name}} · {{form.bio||'Descripción del tallerista'}}</div><label class="span-all">Imagen de portada (opcional)<select v-model="form.coverImage"><option value="">Sin portada</option><option v-for="img in state.meta.images" :key="img" :value="img">{{img.split('/').at(-1)}}</option></select></label><img v-if="form.coverImage" :src="form.coverImage" alt="Portada del tallerista" class="photo-preview span-all" style="max-height:165px;object-fit:cover"/><p class="span-all small muted">Personalización acotada: no se ejecuta HTML ni CSS que cargue el usuario.</p><button class="btn primary" :disabled="busy">Guardar perfil público</button></form></section></div></template>
